macro_rules! deps {
    () => {
        Data!();
        CacheValue!();
        Resource!();
        CacheKey!();
    };
}

macro_rules! resource {
    () => {
        deps!();
        # [doc = ""] pub mod resource { use crate :: blob :: { pipeline , platform :: { CacheKey , CacheValue , Resource } , } ; impl < 'a > Resource < 'a > { pub (crate) fn new (key : & 'a CacheKey , value : & 'a CacheValue) -> Self { Resource { driver_index : value . conversion . driver_index , data : value . conversion . data . map_or (Data :: Missing , | data | match data { pipeline :: Data :: Buffer { is_derived } => Data :: Buffer { buf : & value . buffer , is_derived , } , pipeline :: Data :: Binary { size } => Data :: Binary { size } , }) , mode : value . mode , rela_path : key . location . as_ref () , id : & key . id , } } # [doc = " Produce an iterator over lines, separated by LF or CRLF and thus keeping newlines."] # [doc = ""] # [doc = " Note that this will cause unusual diffs if a file didn't end in newline but lines were added"] # [doc = " on the other side."] # [doc = ""] # [doc = " Suitable to create tokens using [`imara_diff::intern::InternedInput`]."] pub fn intern_source (& self) -> imara_diff :: sources :: ByteLines < 'a > { crate :: blob :: sources :: byte_lines (self . data . as_slice () . unwrap_or_default ()) } # [doc = " Produce an iterator over lines, but remove LF or CRLF."] # [doc = ""] # [doc = " This produces the expected diffs when lines were added at the end of a file that didn't end"] # [doc = " with a newline before the change."] # [doc = ""] # [doc = " Suitable to create tokens using [`imara_diff::intern::InternedInput`]."] pub fn intern_source_strip_newline_separators (& self) -> imara_diff :: sources :: ByteLines < 'a > { crate :: blob :: sources :: byte_lines (self . data . as_slice () . unwrap_or_default ()) } } # [doc = " The data of a diffable resource, as it could be determined and computed previously."] # [derive (Debug , Copy , Clone , Ord , PartialOrd , Eq , PartialEq , Hash)] pub enum Data < 'a > { # [doc = " The object is missing, either because it didn't exist in the working tree or because its `id` was null."] Missing , # [doc = " The textual data as processed to be in a diffable state."] Buffer { # [doc = " The buffer bytes."] buf : & 'a [u8] , # [doc = " If `true`, a [binary to text filter](super::super::Driver::binary_to_text_command) was used to obtain the buffer,"] # [doc = " making it a derived value."] # [doc = ""] # [doc = " Applications should check for this to avoid treating the buffer content as (original) resource content."] is_derived : bool , } , # [doc = " The size that the binary blob had at the given revision, without having applied filters, as it's either"] # [doc = " considered binary or above the big-file threshold."] # [doc = ""] # [doc = " In this state, the binary file cannot be diffed."] Binary { # [doc = " The size of the object prior to performing any filtering or as it was found on disk."] # [doc = ""] # [doc = " Note that technically, the size isn't always representative of the same 'state' of the"] # [doc = " content, as once it can be the size of the blob in git, and once it's the size of file"] # [doc = " in the worktree."] size : u64 , } , } impl < 'a > Data < 'a > { # [doc = " Return ourselves as slice of bytes if this instance stores data."] pub fn as_slice (& self) -> Option < & 'a [u8] > { match self { Data :: Buffer { buf , .. } => Some (buf) , Data :: Binary { .. } | Data :: Missing => None , } } # [doc = " Returns `true` if the data in this instance is derived."] pub fn is_derived (& self) -> bool { match self { Data :: Missing | Data :: Binary { .. } => false , Data :: Buffer { is_derived , .. } => * is_derived , } } } }
    };
}

resource!()